    import random
    import time

    LANGUAGE_WRAPPER = 'Let $S$ be an increasing sequence of all positive integers whose base-{b} representation consists only of digits from the set $D = \\{{digits_str}\\} $. If the integer {X} is the $N^{\\mbox{th}}$ term of $S$, what is the value of $N$?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
def to_base_k_fixed_len(n, k, length):
    if n == 0:
        return [0] * length
    digits = []
    temp_n = n
    while temp_n > 0:
        digits.append(temp_n % k)
        temp_n //= k
    padding = [0] * (length - len(digits))
    return padding + digits[::-1]

def from_base_b(digits, b):
    n = 0
    for d in digits:
        n = n * b + d
    return n

while True:
    b = rng.randint(5, 12)
    k = rng.randint(3, b - 1)
    has_zero = rng.choice([True, False])

    all_digits = list(range(1, b))
    rng.shuffle(all_digits)

    if has_zero:
        D = sorted([0] + all_digits[:k-1])
    else:
        D = sorted(all_digits[:k])

    L = rng.randint(3, 5)

    if has_zero:
        min_N = k**(L-1)
        max_N = k**L - 1
        if min_N > max_N:
            continue
        N = rng.randint(min_N, max_N)

        N_digits_k = to_base_k_fixed_len(N, k, L)
        X_digits_b = [D[d] for d in N_digits_k]
        X = from_base_b(X_digits_b, b)

    else: # not has_zero
        N_less_L = (k * (k**(L - 1) - 1)) // (k - 1)
        N_max_L = (k * (k**L - 1)) // (k - 1)

        if N_less_L + 1 > N_max_L:
            continue
        N = rng.randint(N_less_L + 1, N_max_L)

        m = N - N_less_L - 1
        m_digits_k = to_base_k_fixed_len(m, k, L)
        X_digits_b = [D[d] for d in m_digits_k]
        X = from_base_b(X_digits_b, b)

    if X > 0:
        break

digits_str = ", ".join(map(str, D))
return {
    'b': b,
    'X': X,
    'digits_str': digits_str,
    'N': N
}

    def verifier(assign):
b = assign['b']
X = assign['X']
N_expected = assign['N']
digits_str = assign['digits_str']

try:
    D = sorted([int(d) for d in digits_str.split(', ')])
    k = len(D)

    # Difficulty checks
    if b < 5 or k < 3:
        # Instance is too simple for this problem family
        return False, None

    if X <= 0:
        return False, None # Sequence is of positive integers

    # Convert X to base b
    X_digits_b = []
    temp_X = X
    if temp_X == 0:
        X_digits_b = [0]
    else:
        while temp_X > 0:
            X_digits_b.append(temp_X % b)
            temp_X //= b
        X_digits_b.reverse()

    L = len(X_digits_b)

    if L < 3:
        # Term is too small, problem likely trivial
        return False, None

    # Validate digits and map to indices
    digit_map = {d: i for i, d in enumerate(D)}
    if not all(d in digit_map for d in X_digits_b):
        return False, None # X is not a valid term as its digits are not in D

    c_digits = [digit_map[d] for d in X_digits_b]

    has_zero = (D[0] == 0)

    if has_zero:
        # Standard base conversion from base k to base 10
        N_computed = 0
        for digit in c_digits:
            N_computed = N_computed * k + digit
    else: # not has_zero
        # Bijective numeration system
        # First, find the 0-indexed position 'm' of the term among those of the same length
        m = 0
        for digit in c_digits:
            m = m * k + digit

        # Second, find the count of terms with length less than L
        # This is the sum of a geometric series: k + k^2 + ... + k^(L-1)
        N_less_L = (k * (pow(k, L - 1) - 1)) // (k - 1)

        # The final index is the sum of shorter terms count and the 1-indexed position 'm+1'
        N_computed = N_less_L + m + 1

    if N_computed != N_expected:
        return False, N_computed

    return True, N_computed
except (KeyError, ValueError, TypeError):
    # Catch any potential errors during processing
    return False, None


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
